import { defineConfig } from '/workspace/Avatarrpg/node_modules/@playwright/test/index.mjs';
import base from './source/playwright.config';

const root = '/workspace/avatarrpg-env/resume-368-chimneys';
const label = process.env.FNT_CHIMNEY_LABEL;
if (!label || !/^[a-z0-9-]+$/.test(label)) throw new Error('Unique capture label required');

export default defineConfig({
  ...base,
  testDir: './source/e2e',
  testMatch: /village-(ambience|chimneys)\.review\.ts$/,
  outputDir: `${root}/artifacts/${label}`,
  reporter: [['list'], ['json', { outputFile: `${root}/runs/${label}/playwright-report.json` }]],
  retries: 0,
  maxFailures: 0,
  workers: 1,
  use: { ...base.use, baseURL: 'http://127.0.0.1:4401' },
  projects: [{
    ...base.projects![0],
    name: 'installed-chromium-touch',
    use: { ...base.projects![0]!.use, launchOptions: { executablePath: '/usr/bin/chromium' } },
  }],
  webServer: {
    command: 'npm run preview -- --port 4401 --host 127.0.0.1 --strictPort',
    cwd: `${root}/source`,
    url: 'http://127.0.0.1:4401',
    reuseExistingServer: false,
    timeout: 180_000,
  },
});
